import React, { useState, useEffect, useRef, useCallback } from "react";
import { Camera, Images, Upload, QrCode, X, Download, Loader2, Check, ImageOff, Link as LinkIcon, Sprout, RefreshCw } from "lucide-react";

// ---------------------------------------------------------------------------
// Design tokens
// paper:   #FAF3E6  ink: #2B2B26  green: #3C5844  gold: #B98A3D  rose: #C79090
// display: 'Cormorant Garamond'   body: 'Jost'   utility: 'Space Mono'
// ---------------------------------------------------------------------------

const FONT_IMPORT =
  "@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Jost:wght@300;400;500&family=Space+Mono:wght@400;700&display=swap');";

function Sprig({ className = "", flip = false }) {
  return (
    <svg
      viewBox="0 0 120 24"
      className={className}
      style={{ transform: flip ? "scaleX(-1)" : "none" }}
      fill="none"
    >
      <path d="M2 12 H118" stroke="#B98A3D" strokeWidth="1" opacity="0.5" />
      <path
        d="M60 12 C56 6 50 6 48 12 C50 18 56 18 60 12 C64 6 70 6 72 12 C70 18 64 18 60 12 Z"
        fill="#3C5844"
        opacity="0.85"
      />
      <circle cx="60" cy="12" r="2.2" fill="#B98A3D" />
    </svg>
  );
}

function ArchFrame({ children }) {
  return (
    <div className="relative">
      <svg
        className="absolute inset-0 w-full h-full pointer-events-none"
        viewBox="0 0 400 480"
        preserveAspectRatio="none"
        fill="none"
      >
        <path
          d="M8 480 V120 C8 55 96 8 200 8 C304 8 392 55 392 120 V480"
          stroke="#3C5844"
          strokeWidth="1.5"
          opacity="0.35"
        />
        <path
          d="M22 480 V124 C22 68 104 26 200 26 C296 26 378 68 378 124 V480"
          stroke="#B98A3D"
          strokeWidth="1"
          opacity="0.5"
        />
      </svg>
      <div className="relative pt-14 pb-10 px-8">{children}</div>
    </div>
  );
}

function resizeImage(file, maxDim = 1400, quality = 0.72) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Could not read file"));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("Could not decode image"));
      img.onload = () => {
        let { width, height } = img;
        if (width > height && width > maxDim) {
          height = Math.round((height * maxDim) / width);
          width = maxDim;
        } else if (height > maxDim) {
          width = Math.round((width * maxDim) / height);
          height = maxDim;
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

const COVER_PHOTO = "data:image/jpeg;base64,";

export default function WeddingPhotoShare() {
  const [tab, setTab] = useState("upload"); // upload | gallery | qr
  const [settings, setSettings] = useState({ names: "Arsh & Sanjul", date: "" });
  const [settingsLoaded, setSettingsLoaded] = useState(false);
  const [editingNames, setEditingNames] = useState(false);
  const [guestName, setGuestName] = useState("");
  const [photos, setPhotos] = useState([]);
  const [galleryLoading, setGalleryLoading] = useState(true);
  const [uploadQueue, setUploadQueue] = useState([]); // {id, name, status}
  const [lightbox, setLightbox] = useState(null);
  const [copied, setCopied] = useState(false);
  const cameraInputRef = useRef(null);
  const libraryInputRef = useRef(null);
  const shareUrl = typeof window !== "undefined" ? window.location.href : "";

  // ---- settings (couple names / date) --------------------------------
  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get("event:settings", true);
        if (res && res.value) setSettings(JSON.parse(res.value));
      } catch (e) {
        /* no settings saved yet */
      } finally {
        setSettingsLoaded(true);
      }
    })();
  }, []);

  const saveSettings = async (next) => {
    setSettings(next);
    try {
      await window.storage.set("event:settings", JSON.stringify(next), true);
    } catch (e) {
      console.error("Could not save event details", e);
    }
  };

  // ---- gallery ----------------------------------------------------------
  const loadPhotos = useCallback(async (silent = false) => {
    if (!silent) setGalleryLoading(true);
    try {
      const listRes = await window.storage.list("photo:", true);
      const keys = (listRes && listRes.keys) || [];
      const results = await Promise.all(
        keys.map(async (k) => {
          try {
            const r = await window.storage.get(k, true);
            if (!r) return null;
            const parsed = JSON.parse(r.value);
            return { key: k, ...parsed };
          } catch (e) {
            return null;
          }
        })
      );
      const clean = results.filter(Boolean).sort((a, b) => b.ts - a.ts);
      setPhotos(clean);
    } catch (e) {
      console.error("Could not load photos", e);
    } finally {
      if (!silent) setGalleryLoading(false);
    }
  }, []);

  useEffect(() => {
    loadPhotos();
  }, [loadPhotos]);

  useEffect(() => {
    if (tab === "gallery") loadPhotos();
  }, [tab, loadPhotos]);

  // Quietly poll for new photos while someone is looking at the gallery,
  // so guests see each other's uploads without needing to reload.
  useEffect(() => {
    if (tab !== "gallery") return;
    const id = setInterval(() => loadPhotos(true), 6000);
    return () => clearInterval(id);
  }, [tab, loadPhotos]);

  // ---- upload -------------------------------------------------------
  const handleFiles = async (fileList) => {
    const files = Array.from(fileList).filter((f) => f.type.startsWith("image/"));
    if (files.length === 0) return;

    const jobs = files.map((f) => ({
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      name: f.name,
      status: "processing",
    }));
    setUploadQueue((q) => [...jobs, ...q]);

    await Promise.all(
      files.map(async (file, i) => {
        const job = jobs[i];
        try {
          const dataUrl = await resizeImage(file);
          const key = `photo:${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
          const payload = {
            data: dataUrl,
            by: guestName.trim() || "A guest",
            ts: Date.now(),
          };
          const res = await window.storage.set(key, JSON.stringify(payload), true);
          if (!res) throw new Error("Storage rejected the photo");
          setUploadQueue((q) =>
            q.map((j) => (j.id === job.id ? { ...j, status: "done" } : j))
          );
        } catch (e) {
          console.error(e);
          setUploadQueue((q) =>
            q.map((j) => (j.id === job.id ? { ...j, status: "error" } : j))
          );
        }
      })
    );

    loadPhotos();
    setTimeout(() => {
      setUploadQueue((q) => q.filter((j) => j.status === "processing"));
    }, 3500);
  };

  const onDrop = (e) => {
    e.preventDefault();
    handleFiles(e.dataTransfer.files);
  };

  const copyLink = async () => {
    try {
      await navigator.clipboard.writeText(shareUrl);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (e) {
      /* clipboard may be unavailable; user can select the text field */
    }
  };

  const qrSrc = `https://api.qrserver.com/v1/create-qr-code/?size=440x440&margin=12&color=3C5844&bgcolor=FAF3E6&data=${encodeURIComponent(
    shareUrl
  )}`;

  return (
    <div
      className="min-h-screen w-full"
      style={{ background: "#FAF3E6", fontFamily: "'Jost', sans-serif", color: "#2B2B26" }}
    >
      <style>{`
        ${FONT_IMPORT}
        .display { font-family: 'Cormorant Garamond', serif; }
        .mono { font-family: 'Space Mono', monospace; }
        .tab-btn { transition: color .2s ease, border-color .2s ease; }
        .fade-in { animation: fadeIn .5s ease both; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(6px);} to { opacity: 1; transform: translateY(0);} }
        @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }
        @media (prefers-reduced-motion: reduce) {
          .fade-in { animation: none; }
        }
        input:focus-visible, button:focus-visible, textarea:focus-visible {
          outline: 2px solid #B98A3D;
          outline-offset: 2px;
        }
      `}</style>

      {/* ---------- Header ---------- */}
      <header className="max-w-3xl mx-auto px-6 pt-12 pb-6 text-center">
        <div
          className="w-28 h-28 mx-auto mb-6 rounded-full overflow-hidden border-4"
          style={{ borderColor: "#FAF3E6", boxShadow: "0 0 0 1px #B98A3D, 0 8px 20px rgba(43,43,38,0.18)" }}
        >
          <img src={COVER_PHOTO} alt={`${settings.names}`} className="w-full h-full object-cover" />
        </div>
        <div className="flex items-center justify-center gap-3 mb-3">
          <Sprig className="w-14 h-6" />
          <Sprig className="w-14 h-6" flip />
        </div>
        {editingNames ? (
          <div className="flex flex-col items-center gap-2">
            <input
              autoFocus
              value={settings.names}
              onChange={(e) => setSettings((s) => ({ ...s, names: e.target.value }))}
              onBlur={() => {
                saveSettings(settings);
                setEditingNames(false);
              }}
              onKeyDown={(e) => {
                if (e.key === "Enter") e.currentTarget.blur();
              }}
              className="display text-4xl md:text-5xl text-center bg-transparent border-b"
              style={{ borderColor: "#B98A3D", color: "#2B2B26" }}
            />
          </div>
        ) : (
          <h1
            className="display text-4xl md:text-5xl italic cursor-text"
            style={{ color: "#2B2B26" }}
            onClick={() => setEditingNames(true)}
            title="Click to edit"
          >
            {settingsLoaded ? settings.names : "\u00A0"}
          </h1>
        )}
        <p className="mono text-xs tracking-widest uppercase mt-3" style={{ color: "#8A7A5C" }}>
          share what you saw today
        </p>
      </header>

      {/* ---------- Tabs ---------- */}
      <nav className="max-w-3xl mx-auto px-6 flex justify-center gap-8 border-b" style={{ borderColor: "#E3D9C4" }}>
        {[
          { id: "upload", label: "Add a photo", icon: Camera },
          { id: "gallery", label: "Gallery", icon: ImageOff, iconActive: true },
          { id: "qr", label: "Print QR", icon: QrCode },
        ].map(({ id, label, icon: Icon }) => (
          <button
            key={id}
            onClick={() => setTab(id)}
            className="tab-btn pb-3 pt-1 text-sm mono uppercase tracking-wider flex items-center gap-2 border-b-2"
            style={{
              borderColor: tab === id ? "#3C5844" : "transparent",
              color: tab === id ? "#3C5844" : "#9A9186",
            }}
          >
            {id === "gallery" ? (
              <span className="text-base leading-none">&#10047;</span>
            ) : (
              <Icon className="w-4 h-4" />
            )}
            {label}
            {id === "gallery" && photos.length > 0 && (
              <span
                className="text-[10px] px-1.5 py-0.5 rounded-full"
                style={{ background: "#3C5844", color: "#FAF3E6" }}
              >
                {photos.length}
              </span>
            )}
          </button>
        ))}
      </nav>

      {/* ---------- Content ---------- */}
      <main className="max-w-3xl mx-auto px-6 py-10">
        {tab === "upload" && (
          <div className="fade-in max-w-md mx-auto">
            <ArchFrame>
              <div className="text-center mb-6">
                <p className="display italic text-2xl mb-1">Drop a memory in the frame</p>
                <p className="text-sm" style={{ color: "#6B6255" }}>
                  Photos land in the shared gallery instantly for everyone to see.
                </p>
              </div>

              <input
                type="text"
                value={guestName}
                onChange={(e) => setGuestName(e.target.value)}
                placeholder="Your name (optional)"
                className="w-full mb-4 px-4 py-2 rounded-full border text-sm text-center bg-white/60"
                style={{ borderColor: "#D9CCA9" }}
              />

              <div
                onDragOver={(e) => e.preventDefault()}
                onDrop={onDrop}
                className="rounded-2xl border-2 border-dashed flex flex-col items-center justify-center py-8 px-4 text-center gap-3"
                style={{ borderColor: "#B98A3D", background: "rgba(185,138,61,0.06)" }}
              >
                <Upload className="w-6 h-6" style={{ color: "#3C5844" }} />
                <p className="mono text-xs" style={{ color: "#9A9186" }}>
                  drag photos here, or
                </p>
                <div className="flex gap-3">
                  <button
                    type="button"
                    onClick={() => cameraInputRef.current?.click()}
                    className="flex items-center gap-2 px-4 py-2 rounded-full text-white text-sm"
                    style={{ background: "#3C5844" }}
                  >
                    <Camera className="w-4 h-4" />
                    Take a photo
                  </button>
                  <button
                    type="button"
                    onClick={() => libraryInputRef.current?.click()}
                    className="flex items-center gap-2 px-4 py-2 rounded-full text-sm border"
                    style={{ borderColor: "#B98A3D", color: "#3C5844" }}
                  >
                    <Images className="w-4 h-4" />
                    Choose photos
                  </button>
                </div>
                <input
                  ref={cameraInputRef}
                  type="file"
                  accept="image/*"
                  capture="environment"
                  className="hidden"
                  onChange={(e) => {
                    handleFiles(e.target.files);
                    e.target.value = "";
                  }}
                />
                <input
                  ref={libraryInputRef}
                  type="file"
                  accept="image/*"
                  multiple
                  className="hidden"
                  onChange={(e) => {
                    handleFiles(e.target.files);
                    e.target.value = "";
                  }}
                />
              </div>

              {uploadQueue.length > 0 && (
                <ul className="mt-5 space-y-2">
                  {uploadQueue.map((j) => (
                    <li
                      key={j.id}
                      className="flex items-center justify-between text-xs mono px-3 py-2 rounded-lg bg-white/60"
                      style={{ color: "#6B6255" }}
                    >
                      <span className="truncate max-w-[65%]">{j.name}</span>
                      {j.status === "processing" && (
                        <Loader2 className="w-4 h-4 animate-spin" style={{ color: "#B98A3D" }} />
                      )}
                      {j.status === "done" && <Check className="w-4 h-4" style={{ color: "#3C5844" }} />}
                      {j.status === "error" && <span style={{ color: "#B85C5C" }}>failed</span>}
                    </li>
                  ))}
                </ul>
              )}
            </ArchFrame>
          </div>
        )}

        {tab === "gallery" && (
          <div className="fade-in">
            {galleryLoading ? (
              <div className="flex flex-col items-center py-24" style={{ color: "#9A9186" }}>
                <Loader2 className="w-6 h-6 animate-spin mb-3" />
                <p className="mono text-xs uppercase tracking-widest">Gathering photos</p>
              </div>
            ) : photos.length === 0 ? (
              <div className="text-center py-24">
                <Sprout className="w-8 h-8 mx-auto mb-3" style={{ color: "#B98A3D" }} />
                <p className="display italic text-2xl mb-1">Nothing here yet</p>
                <p className="text-sm" style={{ color: "#6B6255" }}>
                  Be the first to add a photo from the reception.
                </p>
              </div>
            ) : (
              <>
                <div className="flex items-center justify-center gap-3 mb-6">
                  <p className="mono text-xs uppercase tracking-widest" style={{ color: "#9A9186" }}>
                    {photos.length} photo{photos.length !== 1 ? "s" : ""} shared so far
                  </p>
                  <span className="flex items-center gap-1 mono text-[10px] uppercase" style={{ color: "#3C5844" }}>
                    <span
                      className="w-1.5 h-1.5 rounded-full inline-block"
                      style={{ background: "#3C5844", animation: "pulse 2s infinite" }}
                    />
                    live
                  </span>
                  <button
                    onClick={() => loadPhotos()}
                    className="text-xs flex items-center gap-1 mono uppercase"
                    style={{ color: "#B98A3D" }}
                    title="Refresh now"
                  >
                    <RefreshCw className="w-3 h-3" />
                  </button>
                </div>
                <div className="columns-2 sm:columns-3 gap-3 [column-fill:balance]">
                  {photos.map((p) => (
                    <button
                      key={p.key}
                      onClick={() => setLightbox(p)}
                      className="mb-3 block w-full rounded-lg overflow-hidden border break-inside-avoid"
                      style={{ borderColor: "#E3D9C4" }}
                    >
                      <img src={p.data} alt={`Uploaded by ${p.by}`} className="w-full h-auto block" loading="lazy" />
                    </button>
                  ))}
                </div>
              </>
            )}
          </div>
        )}

        {tab === "qr" && (
          <div className="fade-in text-center max-w-sm mx-auto">
            <p className="display italic text-2xl mb-1">For the bench cards</p>
            <p className="text-sm mb-6" style={{ color: "#6B6255" }}>
              Print this QR code and set it wherever guests are sitting. Scanning it opens this exact page.
            </p>
            <div
              className="inline-block p-5 rounded-2xl border bg-white"
              style={{ borderColor: "#E3D9C4" }}
            >
              <img src={qrSrc} alt="QR code linking to this photo-sharing page" width={220} height={220} />
            </div>
            <div
              className="mt-6 flex items-center gap-2 px-4 py-2 rounded-full border text-xs mono"
              style={{ borderColor: "#D9CCA9", color: "#6B6255" }}
            >
              <LinkIcon className="w-3.5 h-3.5 shrink-0" />
              <span className="truncate">{shareUrl}</span>
            </div>
            <button
              onClick={copyLink}
              className="mt-3 mono text-xs uppercase tracking-widest px-5 py-2 rounded-full text-white"
              style={{ background: copied ? "#3C5844" : "#B98A3D" }}
            >
              {copied ? "Copied" : "Copy link"}
            </button>
            <p className="text-xs mt-6" style={{ color: "#9A9186" }}>
              Tip: this link only works once it's published / shared, so guests on their own phones can reach it.
            </p>
          </div>
        )}
      </main>

      <footer className="text-center pb-10 pt-4">
        <Sprig className="w-16 h-6 mx-auto" />
      </footer>

      {/* ---------- Lightbox ---------- */}
      {lightbox && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-4"
          style={{ background: "rgba(43,43,38,0.92)" }}
          onClick={() => setLightbox(null)}
        >
          <div className="relative max-w-lg w-full" onClick={(e) => e.stopPropagation()}>
            <img src={lightbox.data} alt="" className="w-full h-auto rounded-lg" />
            <div className="flex items-center justify-between mt-3 px-1">
              <span className="mono text-xs" style={{ color: "#E3D9C4" }}>
                {lightbox.by} &middot; {new Date(lightbox.ts).toLocaleString()}
              </span>
              <div className="flex gap-3">
                <a
                  href={lightbox.data}
                  download={`wedding-photo-${lightbox.ts}.jpg`}
                  className="text-white/80 hover:text-white"
                  title="Download"
                >
                  <Download className="w-5 h-5" />
                </a>
                <button onClick={() => setLightbox(null)} className="text-white/80 hover:text-white" title="Close">
                  <X className="w-5 h-5" />
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
